function applyPreset(value){snapshot();const d=defaults();journey=false;if(value==='walk'){graphs.legs=d.legs;preset='walk';}else if(value==='walkjump'){graphs.legs=withJump(graphs.legs);preset='walkjump';}else if(value==='sword'){graphs.arms=d.arms;graphs.anim=d.anim;}else if(value==='layered'){graphs.arms=d.arms;graphs.anim=d.anim;const g=graphs.anim,out=g.nodes.find(n=>n.type==='output');out.x=1940;g.nodes.push(make('layer','layer',1600,90));g.edges=g.edges.filter(e=>e.to!=='output');connect(g,'blend','pose','layer','base');connect(g,'slot','pose','layer','blend');connect(g,'layer','pose','output','pose');}else if(value==='keydoor'){graphs.door=d.door;}else if(value==='toggle'){const g={nodes:[make('interactInput','interact',40,65),make('flip','flip',370,70),make('rotate','open',690,30),make('rotate','close',690,390),make('doorRef','door',350,350)],edges:[]};g.nodes[3].values.rotation=[0,0,0];connect(g,'interact','started','flip','in');connect(g,'flip','a','open','in');connect(g,'flip','b','close','in');connect(g,'door','value','open','target');connect(g,'door','value','close','target');graphs.door=g;}else if(value==='fullanim'){graphs.anim=d.anim;}else if(value==='simpleanim'){graphs.anim=simpleAnimation();}engine.graphs=graphs;mode='explore';task=activeTask();usedHelp=true;completed=false;selection=null;updatePanel();$('presetSelect').value=value;renderGraph(true);saveProject();toast('Το preset εφαρμόστηκε. Δεν μετρήθηκε ως δική σου ολοκλήρωση μαθήματος.');}
function simpleAnimation(){const g={nodes:[make('velocity','velocity',40,70),make('lengthXY','speed',330,70),make('locomotion','locomotion',620,70),make('output','output',955,70)],edges:[]};connect(g,'velocity','value','speed','vector');connect(g,'speed','value','locomotion','speed');connect(g,'locomotion','pose','output','pose');return g;}
function swordAnimation(){const g=copy(graphs.anim),locomotion=g.nodes.find(n=>n.type==='locomotion'),output=g.nodes.find(n=>n.type==='output');if(!locomotion||!output)return swordAnimationFrom(simpleAnimation());return swordAnimationFrom(g);}
